def tr(txt,language='pl'):
    if language!='en' or not isinstance(txt,str):return txt
    # Sidebar label contains a decorative symbol preceding a string.
    if txt in STRINGS:return STRINGS[txt]
    stripped=txt.strip()
    if stripped in STRINGS:return txt[:len(txt)-len(txt.lstrip())] + STRINGS[stripped]
    for key,english in STRINGS.items():
        if txt.endswith(key) and len(txt)<len(key)+7:
            return txt[:-len(key)]+english
    return txt

